CREATE OR REPLACE PROCEDURE P_일정산 (p_정산일자 IN VARCHAR2) IS
  v_등급      고객.등급%TYPE;
  v_수수료율  등급별수수료.수수료율%TYPE;
  v_수수료    NUMBER;
BEGIN
  FOR r IN (SELECT 주문번호, 고객번호, 주문금액
            FROM   주문
            WHERE  주문일자 = p_정산일자
            AND    주문상태 = '완료'
            AND    정산여부 = 'N')
  LOOP
    SELECT 등급     INTO v_등급     FROM 고객         WHERE 고객번호 = r.고객번호;
    SELECT 수수료율 INTO v_수수료율 FROM 등급별수수료 WHERE 등급     = v_등급;

    v_수수료 := ROUND(r.주문금액 * v_수수료율);

    INSERT INTO 정산 (정산번호, 주문번호, 정산일자, 정산금액, 수수료)
    VALUES (정산_SEQ.NEXTVAL, r.주문번호, p_정산일자, r.주문금액 - v_수수료, v_수수료);

    UPDATE 주문 SET 정산여부 = 'Y' WHERE 주문번호 = r.주문번호;

    COMMIT;
  END LOOP;
END;
/

